<x-admin-layout :title="$product->exists?'Edit product':'New product'"><p class="notice">Enter prices in paisa: ৳1,200 = 120000. Supply accurate specifications and authentic photography before publishing. Changing an existing SKU creates a new variant; set old variant stock to zero to retire it.</p><form action="/admin/products{{ $product->exists?'/'.$product->id:'' }}" method="post" enctype="multipart/form-data" x-data="{count:{{ max(1,count(old('variants',$product->variants?->toArray()??[]))) }}}">@csrf<div class="form-grid"><label>Name<input name="name" value="{{ old('name',$product->name) }}" required maxlength="150"></label><label>Slug<input name="slug" value="{{ old('slug',$product->slug) }}" required pattern="[a-zA-Z0-9_-]+" maxlength="150"></label><label>Category<select name="category_id" required>@foreach($categories as $c)<option value="{{ $c->id }}" @selected(old('category_id',$product->category_id)==$c->id)>{{ $c->name }}</option>@endforeach</select></label><label>Status<select name="status">@foreach(['draft','published','archived'] as $status)<option @selected(old('status',$product->status)===$status)>{{ $status }}</option>@endforeach</select></label><label>Regular price (paisa)<input type="number" name="price" min="1" value="{{ old('price',$product->price) }}" required></label><label>Sale price (paisa, optional)<input type="number" name="sale_price" min="1" value="{{ old('sale_price',$product->sale_price) }}"></label></div><label>Description<textarea name="description" required rows="5">{{ old('description',$product->description) }}</textarea></label><div class="form-grid">@foreach(['fabric'=>'Fabric composition','fit'=>'Fit','care'=>'Care instructions'] as $key=>$label)<label>{{ $label }}<textarea name="{{ $key }}">{{ old($key,$product->$key) }}</textarea></label>@endforeach</div><div class="inline-form">@foreach(['featured'=>'Featured','new_arrival'=>'New arrival','demo'=>'Demonstration product','noindex'=>'Exclude from search indexing'] as $key=>$label)<label class="check"><input type="checkbox" name="{{ $key }}" value="1" @checked(old($key,$product->$key))>{{ $label }}</label>@endforeach</div><h2>Variants & stock</h2><p class="small">Every size/color combination and SKU must be unique. Stock changes are recorded in inventory history.</p><div class="variants-editor">@php($variants=old('variants',$product->variants?->toArray()?:[['sku'=>'','size'=>'','color'=>'','stock'=>0,'low_stock_threshold'=>(int)($store['low_stock_threshold']??5)]]))@foreach($variants as $index=>$v)<div class="variant-row">@foreach(['sku'=>'SKU','size'=>'Size','color'=>'Color','stock'=>'Stock','low_stock_threshold'=>'Low stock at'] as $field=>$label)<label>{{ $label }}<input name="variants[{{ $index }}][{{ $field }}]" value="{{ $v[$field]??'' }}" @if(in_array($field,['stock','low_stock_threshold'])) type="number" min="0" @endif required></label>@endforeach</div>@endforeach<template x-for="i in Math.max(0,count-{{ count($variants) }})" :key="i"><div class="variant-row">@foreach(['sku'=>'SKU','size'=>'Size','color'=>'Color','stock'=>'Stock','low_stock_threshold'=>'Low stock at'] as $field=>$label)<label>{{ $label }}<input :name="'variants['+({{ count($variants) }}+i-1)+'][{{ $field }}]'" @if(in_array($field,['stock','low_stock_threshold'])) type="number" min="0" value="0" @endif required></label>@endforeach</div></template></div><button type="button" class="text-link" @click="count++">Add variant +</button><h2>Images</h2><label>Upload product images (JPEG, PNG, WebP; max 4 MB each)<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple></label><label>Alt text for new images<input name="image_alt" maxlength="200" value="{{ old('image_alt',$product->name) }}"></label><div class="image-editor">@foreach($product->images??[] as $image)<div><img src="{{ Storage::url($image->path) }}" alt="{{ $image->alt }}" width="100"><label>Alt text<input name="image_alts[{{ $image->id }}]" value="{{ $image->alt }}"></label><label class="check"><input type="checkbox" name="delete_images[]" value="{{ $image->id }}">Delete image</label></div>@endforeach</div><h2>Search engine appearance</h2>@if($product->images->isNotEmpty())<label>Social sharing image<select name="og_image_id"><option value="">Use default product image</option>@foreach($product->images as $image)<option value="{{ $image->id }}" @selected($product->og_image===$image->path)>{{ $image->alt }}</option>@endforeach</select></label>@endif<label>SEO title<input name="seo_title" maxlength="160" value="{{ old('seo_title',$product->seo_title) }}"></label><label>Meta description<textarea name="meta_description" maxlength="320">{{ old('meta_description',$product->meta_description) }}</textarea></label>@if($product->exists && (!$product->seo_title||!$product->meta_description||$product->images->isEmpty()))<p class="notice">Before launch: add a unique SEO title, meta description, and authentic product photos.</p>@endif<button class="button">Save product ↗</button>@if($product->status==='published')<a class="text-link" href="/product/{{ $product->slug }}">View product ↗</a>@endif</form></x-admin-layout>